from pathlib import Path
import json,csv,hashlib
from PIL import Image,ImageOps,ImageDraw,ImageFont
R=Path(__file__).resolve().parent;read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
fetch=read(R/'FETCH_RECEIPT.json');files={x['dataset_path']:x for x in fetch['files']}
choices=[('kangaroo',1,'priority','源片连续三轮落地/蹬伸/腾空，双后腿清楚，动作阶段比另外两条更丰富。目标为全身鸸鹋，腿和脚可见、草地可承接跳跃，主体几何与袋鼠差异仍大。原片伴随镜头跟随，不能将背景平移解释为主体动作。约0.5–1.25、2.5–3.25、4.5–5.25秒有相似腾起阶段；这些是人工观察范围，不是精确GT。'),('dogjump',2,'priority','源为侧面犬抬头、张嘴、前爪抬起后身体回落，约2.25–4.75秒包含主要变化。目标狼为完整侧身犬科，四肢可见，结构接近；雪地地面清楚。原片后腿和地面出画，不能标注精确落地。官方caption的barking属于声音语义，静帧只能确认张嘴。'),('dogstand',2,'low_density_control','原片前1.75秒变化很少，约2.0–2.75秒躯干竖起，之后维持；高点头会出上边界。目标兔子完整、地面清楚，能检查站起时刻；这是一个单次缓慢起身动作，列为低动作变化对照，不能用于凑动作密集样本。')]
font=ImageFont.truetype('/System/Library/Fonts/Supplemental/Arial.ttf',25);selected=[]
for source,index,status,note in choices:
 csvpath=R/'assets/benchmark/captions/animal'/source/'val_image.csv';row=list(csv.DictReader(csvpath.open()))[index]
 target=R/'assets'/row['path'];sourcepath='benchmark/reference_videos/animal/'+source+'.mp4';sourcefile=R/'assets'/sourcepath
 grid=Image.open(R/(source+'_source_all49.png'));can=Image.new('RGB',(1680,1630),'black');d=ImageDraw.Draw(can)
 im=ImageOps.contain(Image.open(target).convert('RGB'),(600,250));can.paste(im,(20,20));name=source+'__'+target.stem
 for y,s in [(40,name),(90,f'Official pair: animal/{source}, val_image.csv row {index+1}'),(140,'Target image above; all49 original frames below')]:d.text((650,y),s,font=font,fill='white')
 can.paste(grid,(0,290));out=R/(name+'_source_target.png');can.save(out)
 selected.append({'pair_id':name,'source_id':source,'official_pair_location':f'benchmark/captions/animal/{source}/val_image.csv','official_row_zero_based':index,'official_caption':row['caption'],'csv_sha256':sha(csvpath),'source':files[sourcepath],'target':files[row['path']],'source_category':'animal','new_original_source':True,'priority_status':status,'review':note,'contact_sheet':str(out),'human_pose_observer_applicable':False,'original_frames':49,'original_fps':'8/1','first_pts':0,'last_pts':6,'original_duration_seconds':6.125,'generation_or_GPU_started':False})
inv=read(R/'PUBLIC_INVENTORY.json');dedup=read(R/'LOCAL_SOURCE_DEDUP.json')
assert not dedup['unseen_animal_or_camera_hits']
allpairs=[]
for p in (R/'assets/benchmark/captions').rglob('val_image.csv'):
 for i,row in enumerate(csv.DictReader(p.open())):allpairs.append((p.parts[-3],p.parts[-2],row['path']))
assert len(set(allpairs))==len(allpairs)==89
report={'schema':'flexiact-public-new-source-review-v1','revision':fetch['revision'],'current_revision_matches':fetch['current_repository']['same_as_pinned'],'public_raw_originals':15,'public_exact_hash_distinct_originals':15,'public_val_pairs':89,'public_categories':{'human':{'originals':8,'pairs':46},'animal':{'originals':3,'pairs':11},'camera':{'originals':4,'pairs':32}},'previously_used_originals':8,'remaining_raw_originals':7,'remaining_human_originals':0,'remaining_non_camera_subject_motion_originals':3,'priority_new_originals':2,'low_density_control_originals':1,'paper_claim':{'action_categories':25,'video_image_pairs':250,'source':'https://arxiv.org/html/2505.03730v1#S4.SS1'},'public_vs_paper':'Published paper inventory and accessible repository inventory differ; do not replace published250 denominator with the current89row release or call crop files independent actions. No undisclosed assets inferred.','official_data_link':'https://github.com/shiyi-zh0408/FlexiAct#-getting-started','selected':selected,'camera_exclusion':'4 sequences explicitly catalogued as camera motion; no remaining independent human body-action source. Camera-source clips not downloaded for this body-action selection.','all_remaining_animal_pairs':11,'metadata_notes':['dogstand animal_ciwei1 target appears as a sculpted hedgehog-like object; not prioritized for natural animal articulation.','dogjump tiger/deer captions reuse barking; retain official captions without claiming visible audio evidence.','Original49frames at8fps are low temporal resolution. A later24fps repeated preparation does not add independent event timing precision.','Human DWPose observer cannot directly provide timing labels for these animal sources. Official point-track MF can still be computed, but action-stage inspection must remain separate.'],'files_downloaded_or_reused':len(fetch['files']),'bytes_downloaded_or_reused':sum(f['bytes']for f in fetch['files']),'GPU_started':False}
(R/'NEW_SOURCE_REVIEW.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
lines=['FlexiAct公开库：新增原片筛选','','当前公开revision与已固定版本相同（69d7747f93e1b913a3dca306bf8e91ee74fea7d4）。完整文件树共15个独立原片、89条官方source×target行：人体8原片/46对，动物3原片/11对，镜头4原片/32对。15个原片内容hash互异，crop文件与新增目标身份不重复计作动作源。','','我们已用过全部8个人体原片：chest、crouch、fitness、one_leg、rotate以及human2animal_1/2/3。R85三个源均在这8条内。扫描10份本地Flex生产contract，没有这3个动物源的记录。因此剩余7个原片中，可研究主体动作的是3条动物片，另外4条属于镜头运动。当前公开库无法提供5–8条尚未使用的人体动作原片。','','推荐2条新原片，另1条低动作变化对照：']
for p in selected:lines+=['',p['pair_id']+'；官方CSV行'+str(p['official_row_zero_based']+1)+'；'+p['priority_status'],p['review'],'图：'+p['contact_sheet']]
lines+=['','这3条原片均为49帧、8fps、6.125秒。已检查全部49帧。人物姿态观察器不能直接用于动物；需以原始时刻下的动物动作阶段与点轨迹分别评价。','','论文§4.1写25个动作类别/250对；作者官方GitHub指向的公开HF当前版本实际提供15个原片/89行val_image配对。这两种口径分别记录，不能把当前文件数说成论文完整基准，也不能凭未公开内容补足5条。','论文：https://arxiv.org/html/2505.03730v1#S4.SS1','官方代码及数据入口：https://github.com/shiyi-zh0408/FlexiAct','固定数据：https://huggingface.co/datasets/shiyi0408/FlexiAct/tree/69d7747f93e1b913a3dca306bf8e91ee74fea7d4','','44个必要元数据/源视频/目标图片总7.65MB，已逐文件校验Git blob或LFS SHA；不下载模型，不执行GPU。']
(R/'REPORT.txt').write_text('\n'.join(lines)+'\n')
(R/'VISUAL_REVIEW.json').write_text(json.dumps({'passed':True,'all3source49frames_visually_inspected':True,'all11target_images_visually_inspected':True,'source_crop':'full original content; no artificial crop or time alignment','new_source_count':3,'dense_multi_action_count':0,'cyclic_contact_phase_source':'kangaroo','single_event_source':'dogjump','low_density_control':'dogstand','limits':'Visible phase evidence; no generated quality result or precise humanGT claim'},indent=2)+'\n')
(R/'ARTIFACT_MANIFEST.json').write_text(json.dumps({str(p.relative_to(R)):{'bytes':p.stat().st_size,'sha256':sha(p)}for p in R.rglob('*')if p.is_file()and p.name!='ARTIFACT_MANIFEST.json'},indent=2)+'\n')
print(json.dumps({'report':str(R/'REPORT.txt'),'selected':[p['pair_id']for p in selected],'new_sources':3,'priority':2},ensure_ascii=False))
